+// Page returns the items on the zero-based page. The last page may hold
+// fewer than size items.
+func Page(items []string, page, size int) []string {
+	start := page * size
+	if start >= len(items) {
+		return nil
+	}
+	end := start + size
+	return items[start:end]
+}
